// Independent reference port of mapbox/earcut.hpp

const NULL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prev_z: usize,
    next_z: usize,
    steiner: bool,
}

struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

macro_rules! n {
    ($s:expr, $i:expr) => {
        $s.nodes[$i]
    };
}

impl Earcut {
    fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;
        if points.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }
        self.nodes.reserve(len * 3 / 2);

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NULL || n!(self, outer_node).prev == n!(self, outer_node).next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = n!(self, outer_node).next;
            self.min_x = n!(self, outer_node).x;
            self.max_x = self.min_x;
            self.min_y = n!(self, outer_node).y;
            self.max_y = self.min_y;
            loop {
                let x = n!(self, p).x;
                let y = n!(self, p).y;
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = n!(self, p).next;
                if p == outer_node {
                    break;
                }
            }
            let size = if self.max_x - self.min_x > self.max_y - self.min_y {
                self.max_x - self.min_x
            } else {
                self.max_y - self.min_y
            };
            self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
        }

        self.earcut_linked(outer_node, 0);
    }

    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last = NULL;

        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NULL {
            let nx = n!(self, last).next;
            if self.equals(last, nx) {
                self.remove_node(last);
                last = nx;
            }
        }

        self.vertices += len;
        last
    }

    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.construct(i as u32, pt[0], pt[1]);
        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let ln = self.nodes[last].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = last;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let pn = self.nodes[p].next;
        let pp = self.nodes[p].prev;
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        let pz = self.nodes[p].prev_z;
        let nz = self.nodes[p].next_z;
        if pz != NULL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NULL {
            self.nodes[nz].prev_z = pz;
        }
    }

    fn filter_points(&mut self, start: usize, end_in: usize) -> usize {
        if start == NULL {
            return NULL;
        }
        let mut end = if end_in == NULL { start } else { end_in };
        let mut p = start;
        let mut again;
        loop {
            again = false;
            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;
                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = pn;
            }
            if !(again || p != end) {
                break;
            }
        }
        end
    }

    fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
        let mut ear = ear_in;
        if ear == NULL {
            return;
        }

        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is {
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                ear = self.nodes[next].next;
                stop = self.nodes[next].next;
                continue;
            }

            ear = next;

            if ear == stop {
                if pass == 0 {
                    let f = self.filter_points(ear, NULL);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    let f = self.filter_points(ear, NULL);
                    let e = self.cure_local_intersections(f);
                    self.earcut_linked(e, 2);
                } else if pass == 2 {
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if self.point_in_triangle(
                self.nodes[a].x,
                self.nodes[a].y,
                self.nodes[b].x,
                self.nodes[b].y,
                self.nodes[c].x,
                self.nodes[c].y,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }
        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let min_tx = fmin(ax, fmin(bx, cx));
        let min_ty = fmin(ay, fmin(by, cy));
        let max_tx = fmax(ax, fmax(bx, cx));
        let max_ty = fmax(ay, fmax(by, cy));

        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let ear_prev = self.nodes[ear].prev;
        let ear_next = self.nodes[ear].next;

        let mut p = self.nodes[ear].next_z;
        while p != NULL && self.nodes[p].z <= max_z {
            if p != ear_prev
                && p != ear_next
                && self.point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        let mut p = self.nodes[ear].prev_z;
        while p != NULL && self.nodes[p].z >= min_z {
            if p != ear_prev
                && p != ear_next
                && self.point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        let mut start = start_in;
        if start == NULL {
            return NULL;
        }
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                self.remove_node(p);
                let pn2 = self.nodes[p].next;
                self.remove_node(pn2);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        self.filter_points(p, NULL)
    }

    fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    let mut c = self.split_polygon(a, b);

                    let an = self.nodes[a].next;
                    a = self.filter_points(a, an);
                    let cn = self.nodes[c].next;
                    c = self.filter_points(c, cn);

                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    fn eliminate_holes(&mut self, _points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        outer_node
    }

    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NULL;
        self.nodes[p].prev_z = NULL;
        self.sort_linked(p);
    }

    fn sort_linked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size: i32 = 1;
        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }
                    self.nodes[e].prev_z = tail;
                    tail = e;
                }
                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }
            in_size *= 2;
        }
    }

    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        let mut x: i32 = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y: i32 = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x.wrapping_shl(8))) & 0x00FF00FF;
        x = (x | (x.wrapping_shl(4))) & 0x0F0F0F0F;
        x = (x | (x.wrapping_shl(2))) & 0x33333333;
        x = (x | (x.wrapping_shl(1))) & 0x55555555;

        y = (y | (y.wrapping_shl(8))) & 0x00FF00FF;
        y = (y | (y.wrapping_shl(4))) & 0x0F0F0F0F;
        y = (y | (y.wrapping_shl(2))) & 0x33333333;
        y = (y | (y.wrapping_shl(1))) & 0x55555555;

        x | (y.wrapping_shl(1))
    }

    fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    }

    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bp = self.nodes[b].prev;
        let bn = self.nodes[b].next;
        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true;
        }
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }
        false
    }

    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        qx <= fmax(px, rx) && qx >= fmin(px, rx) && qy <= fmax(py, ry) && qy >= fmin(py, ry)
    }

    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            if ((self.nodes[p].y > py) != (self.nodes[pn].y > py))
                && self.nodes[pn].y != self.nodes[p].y
                && (px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - self.nodes[p].y)
                        / (self.nodes[pn].y - self.nodes[p].y)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.construct(ai, ax, ay);
        let b2 = self.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }
}

fn sign(v: f64) -> i32 {
    ((0.0 < v) as i32) - ((v < 0.0) as i32)
}

fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && (b[i] == b' ' || (b[i] >= 0x09 && b[i] <= 0x0d)) {
        i += 1;
    }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let mut acc: i64 = 0;
    let mut of = false;
    while i < b.len() && b[i].is_ascii_digit() {
        let d = (b[i] - b'0') as i64;
        if !of {
            match acc.checked_mul(10).and_then(|v| v.checked_add(d)) {
                Some(v) => acc = v,
                None => of = true,
            }
        }
        i += 1;
    }
    let v: i64 = if of {
        if neg {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if neg {
        -acc
    } else {
        acc
    };
    v as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 19;
    if args.len() > 1 {
        n = c_atoi(&args[1]);
    }

    let mut fractal: Vec<[f64; 2]> = Vec::new();
    let lim = n.wrapping_mul(2);
    let mut i: i32 = 0;
    while i < lim {
        let t = (i as f64) / (lim as f64);
        let x = t * 3.0;
        let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
        fractal.push([x, y]);
        i += 1;
    }
    fractal.push([3.0, 0.0]);
    fractal.push([0.0, 0.0]);

    let polygon = vec![fractal];

    let mut e = Earcut::new();
    e.run(&polygon);

    let mut out = String::new();
