//! C `atoi` semantics.
//!
//! `std::atoi(s)` is specified as `(int)strtol(s, nullptr, 10)` with undefined
//! behaviour on overflow. glibc's `strtol` saturates at `LONG_MAX`/`LONG_MIN`
//! and the narrowing cast to `int` keeps the low 32 bits, which is what the
//! reference binary does; we reproduce that exactly.

/// Parse a string the way C's `atoi` does: skip leading whitespace, accept an
/// optional sign, consume decimal digits, and stop at the first character that
/// is not a digit. Anything unparseable yields `0`.
pub fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0usize;

    // isspace(): space, \t, \n, \v, \f, \r
    while i < b.len() && (b[i] == b' ' || (0x09..=0x0d).contains(&b[i])) {
        i += 1;
    }

    let mut negative = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        negative = b[i] == b'-';
        i += 1;
    }

    let mut acc: i64 = 0;
    let mut overflowed = false;
    while i < b.len() && b[i].is_ascii_digit() {
        if !overflowed {
            let digit = i64::from(b[i] - b'0');
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    let wide = if overflowed {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    wide as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn matches_c_semantics() {
        assert_eq!(atoi("19"), 19);
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi("12abc"), 12);
        assert_eq!(atoi(" 5"), 5);
        assert_eq!(atoi("+3"), 3);
        assert_eq!(atoi("-5"), -5);
        assert_eq!(atoi("3.9"), 3);
        assert_eq!(atoi("0x5"), 0);
        assert_eq!(atoi("007"), 7);
        // glibc saturates to LONG_MAX, then truncates to int.
        assert_eq!(atoi("999999999999999999999"), -1);
    }
}

