//! Arena-backed node storage for the triangulator.
//!
//! The C++ original threads raw `Node*` pointers through every routine and
//! relies on pointer identity for loop termination. We keep the same shape by
//! storing nodes in a flat arena and using `usize` handles, with [`NULL`]
//! standing in for `nullptr`.

/// Sentinel handle standing in for C++'s `nullptr`.
pub const NULL: usize = usize::MAX;

/// A vertex in a circular doubly-linked polygon ring.
#[derive(Clone, Debug)]
pub struct Node {
    /// Index of this vertex in the caller's flattened vertex list.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous / next vertex in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous / next node in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Whether this is a Steiner point.
    pub steiner: bool,
}

/// Flat arena of [`Node`]s. Handles stay valid for the lifetime of a
/// triangulation, which matters because the C++ code holds "pointers" across
/// allocations of new nodes (`split_polygon`).
#[derive(Default)]
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Self {
        Arena { nodes: Vec::new() }
    }

    pub fn reserve(&mut self, additional: usize) {
        self.nodes.reserve(additional);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
    }

    pub fn len(&self) -> usize {
        self.nodes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.nodes.is_empty()
    }

    /// Equivalent of the C++ `nodes.construct(i, x, y)`.
    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        self.nodes.len() - 1
    }
}

impl std::ops::Index<usize> for Arena {
    type Output = Node;

    #[inline]
    fn index(&self, idx: usize) -> &Node {
        &self.nodes[idx]
    }
}

impl std::ops::IndexMut<usize> for Arena {
    #[inline]
    fn index_mut(&mut self, idx: usize) -> &mut Node {
        &mut self.nodes[idx]
    }
}

