//! Scalar helpers used throughout the triangulator.
//!
//! These mirror the free-standing arithmetic of the C++ header exactly,
//! including comparison operators — the ear test is sign-sensitive, so `>=`
//! versus `>` changes the emitted triangulation.

/// `(0 < val) - (val < 0)`, the C++ `sign` helper.
#[inline]
pub fn sign(val: f64) -> i32 {
    i32::from(0.0 < val) - i32::from(val < 0.0)
}

/// `std::min<double>` — returns `b` only when `b < a`, matching C++ ordering
/// semantics (and therefore its NaN behaviour) rather than `f64::min`.
#[inline]
pub fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>` — returns `b` only when `a < b`.
#[inline]
pub fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

/// Signed area of the triangle `p q r`, doubled. Negative means convex under
/// earcut's winding convention.
#[inline]
pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// Is `p` inside (or on the boundary of) triangle `a b c`?
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

