//! Node-level geometric predicates — the C++ member functions that take
//! `Node*` arguments.

use super::geom::{area_xy, fmax, fmin, sign};
use super::Earcut;

impl Earcut {
    /// Doubled signed area of the triangle `p q r`.
    #[inline]
    pub fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let n = &self.nodes;
        area_xy(n[p].x, n[p].y, n[q].x, n[q].y, n[r].x, n[r].y)
    }

    /// Exact coordinate equality (not an epsilon comparison — earcut relies on
    /// bit equality here).
    #[inline]
    pub fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    /// Do segments `p1q1` and `p2q2` intersect, including collinear touching?
    pub fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // Collinear special cases.
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// For collinear `p`, `q`, `r`: does `q` lie within the bounding box of
    /// segment `pr`?
    pub fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let n = &self.nodes;
        n[q].x <= fmax(n[p].x, n[r].x)
            && n[q].x >= fmin(n[p].x, n[r].x)
            && n[q].y <= fmax(n[p].y, n[r].y)
            && n[q].y >= fmin(n[p].y, n[r].y)
    }

    /// Does the diagonal `ab` cross any polygon edge?
    pub fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                return false;
            }
        }
    }

    /// Does the diagonal `ab` lie inside the polygon's sector at `a`?
    pub fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Does the midpoint of `ab` fall inside the polygon? (Even-odd ray cast.)
    pub fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;

        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            let (pxx, pyy) = (self.nodes[p].x, self.nodes[p].y);
            let (nxx, nyy) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((pyy > py) != (nyy > py))
                && nyy != pyy
                && (px < (nxx - pxx) * (py - pyy) / (nyy - pyy) + pxx)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                return inside;
            }
        }
    }

    /// Can `ab` be used to split the polygon in two?
    pub fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bn = self.nodes[b].next;
        let bp = self.nodes[b].prev;

        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            // doesn't intersect other edges
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// Whether sector `m` fully contains sector `p`.
    pub fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let mp = self.nodes[m].prev;
        let mn = self.nodes[m].next;
        let pp = self.nodes[p].prev;
        let pn = self.nodes[p].next;
        self.area(mp, m, pp) < 0.0 && self.area(pn, m, mn) < 0.0
    }
}

