//! Z-order (Morton) curve hashing used to speed up the ear test on larger
//! polygons.
//!
//! `earcut.hpp` switches this on once the input exceeds 80 vertices, so both
//! the plain and the hashed ear tests have to be bit-faithful.

use super::node::NULL;
use super::Earcut;

impl Earcut {
    /// Interleave the coordinates of `(x_, y_)` into a Morton code.
    ///
    /// Coordinates are first mapped into the non-negative 15-bit integer range
    /// by `(v - min) * inv_size`; C++ `static_cast<int32_t>` truncates toward
    /// zero, which is also what Rust's `as i32` does for in-range values.
    pub fn z_order(&self, x_: f64, y_: f64) -> i32 {
        let mut x: i32 = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y: i32 = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | x.wrapping_shl(8)) & 0x00FF_00FF;
        x = (x | x.wrapping_shl(4)) & 0x0F0F_0F0F;
        x = (x | x.wrapping_shl(2)) & 0x3333_3333;
        x = (x | x.wrapping_shl(1)) & 0x5555_5555;

        y = (y | y.wrapping_shl(8)) & 0x00FF_00FF;
        y = (y | y.wrapping_shl(4)) & 0x0F0F_0F0F;
        y = (y | y.wrapping_shl(2)) & 0x3333_3333;
        y = (y | y.wrapping_shl(1)) & 0x5555_5555;

        x | y.wrapping_shl(1)
    }

    /// Interlink the ring's nodes into a z-order-sorted list.
    pub fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let tail = self.nodes[p].prev_z;
        self.nodes[tail].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    /// Bottom-up merge sort of a doubly-linked list along `prev_z`/`next_z`.
    ///
    /// The `<=` tie-break keeps the sort stable, which the triangulation order
    /// depends on.
    pub fn sort_linked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }
                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }
            in_size *= 2;
        }
    }
}

