//! Hole elimination: each hole is joined to the outer ring by a bridge
//! diagonal, turning the multi-ring input into a single ring.
//!
//! `test19` feeds a single ring, so none of this runs for that program; it is
//! here so the ported library covers the same surface as `earcut.hpp`.

use super::node::NULL;
use super::Earcut;

impl Earcut {
    /// Link every hole into the outer ring, left to right.
    pub fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node_in: usize) -> usize {
        let mut outer_node = outer_node_in;

        let mut queue: Vec<usize> = Vec::new();
        for ring in points.iter().skip(1) {
            let list = self.linked_list(ring, false);
            if list != NULL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Splice a single hole into the outer ring.
    pub fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NULL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // Filter collinear points around the cuts.
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, brn);

        // The bridge node itself may have been filtered away.
        let bn = self.nodes[bridge].next;
        self.filter_points(bridge, bn)
    }

    /// Find the outer-ring vertex a hole should be bridged to.
    pub fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NULL;

        // Cast a ray to the left from the hole's leftmost vertex; the hit
        // segment's endpoint with the lesser x is the candidate.
        let mut p = outer_node;
        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y && hy >= self.nodes[pn].y && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[pn].x {
                        p
                    } else {
                        pn
                    };
                    if x == hx {
                        // The hole touches the outer segment; take the
                        // leftmost endpoint straight away.
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NULL {
            return NULL;
        }

        // Look for vertices inside the triangle formed by the hole vertex, the
        // ray hit and the candidate endpoint; if any exist, take the one with
        // the minimum angle to the ray instead.
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mut mx = self.nodes[m].x;
        let mut my = self.nodes[m].y;

        let mut p = m;
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && super::geom::point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = (hy - py).abs() / (hx - px);

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    mx = self.nodes[m].x;
                    my = self.nodes[m].y;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Leftmost (then lowest) node of a ring.
    pub fn get_leftmost(&self, start: usize) -> usize {
        let mut leftmost = start;
        let mut p = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                return leftmost;
            }
        }
    }
}

