//! The ear-clipping core and its three recovery passes.
//!
//! Pass 0 is the plain sweep. If it stalls, pass 1 re-runs after filtering
//! degenerate points, pass 2 cures small local self-intersections, and pass 3
//! (reached as `pass == 2`) splits the remaining polygon along a valid
//! diagonal. Self-intersecting input — which `test19` supplies — spends most
//! of its time in those recovery paths, so their order and index-emission
//! sequence are what determine the output.

use super::geom::{fmax, fmin, point_in_triangle};
use super::node::NULL;
use super::Earcut;

impl Earcut {
    /// Build a circular doubly-linked list from a ring, in the requested
    /// winding order.
    pub fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NULL;

        // Original winding order of the ring (shoelace sum).
        let mut sum = 0.0f64;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NULL {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = next;
            }
        }

        self.vertices += len;
        last
    }

    /// Append a node after `last` in the ring.
    pub fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.nodes.construct(i as u32, pt[0], pt[1]);

        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    /// Unlink `p` from both the ring and the z-order list.
    ///
    /// `p`'s own `prev`/`next` are deliberately left intact: callers walk off a
    /// just-removed node.
    pub fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NULL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NULL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    /// Drop duplicate and collinear vertices between `start` and `end`.
    pub fn filter_points(&mut self, start: usize, end_in: usize) -> usize {
        if start == NULL {
            return NULL;
        }
        let mut end = if end_in == NULL { start } else { end_in };

        let mut p = start;
        loop {
            let mut again = false;

            let next = self.nodes[p].next;
            let prev = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
