    /// Cut off triangles at points where edge `(v[i-1], v[i])` crosses
    /// `(v[i+1], v[i+2])`.
    pub fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        if start_in == NULL {
            return NULL;
        }
        let mut start = start_in;
        let mut p = start;

        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
