    /// Split the polygon along the first valid diagonal and recurse on both
    /// halves.
    pub fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            let a_prev = self.nodes[a].prev;
            while b != a_prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
