                    let mut c = self.split_polygon(a, b);

                    // Filter collinear points around the cuts.
                    let an = self.nodes[a].next;
                    a = self.filter_points(a, an);
                    let cn = self.nodes[c].next;
                    c = self.filter_points(c, cn);

                    // Run earcut on each half.
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                return;
            }
        }
    }

    /// Link two polygon vertices with a bridge, splitting one ring into two
    /// (or joining two rings into one).
    pub fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);

        let a2 = self.nodes.construct(ai, ax, ay);
        let b2 = self.nodes.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }
}

