    /// Build a circular doubly-linked list from a ring, in the requested
    /// winding order.
    pub fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NULL;

        // Original winding order of the ring (shoelace sum).
        let mut sum = 0.0f64;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NULL {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = next;
            }
        }

        self.vertices += len;
        last
    }

