    pub fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.nodes.construct(i as u32, pt[0], pt[1]);

        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
