///     double t = double(i) / (n * 2);
///     double x = t * 3.0;
///     double y = std::sin(t * 10.0) * std::exp(-t) * 2.0 + 1.0;
///     fractal.push_back({x, y});
/// }
/// fractal.push_back({3.0, 0.0});
/// fractal.push_back({0.0, 0.0});
/// ```
///
/// `n * 2` is `int` arithmetic in C++, so it is reproduced with wrapping
/// 32-bit multiplication here. A non-positive count simply skips the loop and
/// leaves the two closing points.
pub fn fractal_ring(n: i32) -> Vec<[f64; 2]> {
    let count = n.wrapping_mul(2);

    let mut fractal: Vec<[f64; 2]> = Vec::new();
    let mut i: i32 = 0;
    while i < count {
        let t = f64::from(i) / f64::from(count);
        let x = t * 3.0;
        let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
        fractal.push([x, y]);
        i += 1;
    }

    fractal.push([3.0, 0.0]);
    fractal.push([0.0, 0.0]);

    fractal
}

#[cfg(test)]
mod tests {
    use super::fractal_ring;

    #[test]
    fn closing_points_always_present() {
        assert_eq!(fractal_ring(0), vec![[3.0, 0.0], [0.0, 0.0]]);
        assert_eq!(fractal_ring(-7), vec![[3.0, 0.0], [0.0, 0.0]]);
        assert_eq!(fractal_ring(3).len(), 8);
    }
}

