//! Pure-Rust port of `mapbox::earcut` (the `earcut.hpp` header-only library).
//!
//! Layout mirrors the C++ header:
//!
//! * [`node`] – the `Node` struct and its arena
//! * [`geom`] – scalar geometry helpers (`area`, `sign`, `pointInTriangle`, …)
//! * [`predicates`] – node-level predicates (`intersects`, `locallyInside`, …)
//! * [`zorder`] – the z-order curve hash (`zOrder`, `indexCurve`, `sortLinked`)
//! * [`triangulate`] – the ear-clipping core and its recovery passes
//! * [`holes`] – hole elimination via bridge diagonals
//!
//! The entry point is [`earcut`].

pub mod geom;
pub mod holes;
pub mod node;
pub mod predicates;
pub mod triangulate;
pub mod zorder;

use node::{Arena, NULL};

/// Triangulate a polygon given as a list of rings (outer ring first, holes
/// after) and return a flat list of triangle vertex indices.
///
/// Indices refer to the concatenation of all rings, in the order given.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut state = Earcut::new();
    state.run(polygon);
    state.indices
}

/// Triangulator state — the C++ `detail::Earcut<N>` class.
pub struct Earcut {
    pub nodes: Arena,
    pub indices: Vec<u32>,
    pub vertices: usize,

    pub hashing: bool,
    pub min_x: f64,
    pub max_x: f64,
    pub min_y: f64,
    pub max_y: f64,
    pub inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Arena::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// `Earcut<N>::operator()(const Polygon& points)`.
    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        // The shape is considered "simple" while the running vertex budget of
        // 80 has not been exhausted; once it goes negative we switch on the
        // z-order hash. Note the loop stops early, exactly as in C++, so `len`
        // is only a lower bound on the true vertex count.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut ring = 0usize;
        while threshold >= 0 && ring < points.len() {
            threshold -= points[ring].len() as i32;
            len += points[ring].len();
            ring += 1;
        }

        // Estimate the size of the node arena, as the C++ pool does.
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NULL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.hashing = threshold < 0;
        if self.hashing {
            self.compute_bbox(outer_node);
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Polygon bounding box plus the `inv_size` scale used by [`zorder`].
    fn compute_bbox(&mut self, outer_node: usize) {
        self.min_x = self.nodes[outer_node].x;
        self.max_x = self.min_x;
        self.min_y = self.nodes[outer_node].y;
        self.max_y = self.min_y;

        let mut p = self.nodes[outer_node].next;
        loop {
            let x = self.nodes[p].x;
            let y = self.nodes[p].y;
            self.min_x = geom::fmin(self.min_x, x);
            self.min_y = geom::fmin(self.min_y, y);
            self.max_x = geom::fmax(self.max_x, x);
            self.max_y = geom::fmax(self.max_y, y);
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        // minX, minY and inv_size transform coords into the 15-bit integer
        // range the z-order curve works in.
        let size = geom::fmax(self.max_x - self.min_x, self.max_y - self.min_y);
        self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
    }
}
